"""Generate the final report only from completed, verified artifacts."""
from common import *
import datetime
from collections import Counter

def table(headers,rows):
    def esc(x):return str(x).replace('|','\\|').replace('\n',' ')
    return '\n'.join(['| '+' | '.join(headers)+' |','|'+'|'.join(['---']*len(headers))+'|']+['| '+' | '.join(esc(v) for v in r)+' |' for r in rows])+'\n'
def f(x):return 'n/a' if x is None else f'{x:.6f}'
def run():
    out=V2/'run';verification=read(out/'verification.json');selection=read(out/'frozen_selection.json');result=read(out/'confirmation_results.json')
