    env=read(V2/'environment.json');split=read(V2/'split.json');data=split['records'];folds=Counter(r['fold'] for r in data);sampling=read(out/'training_sampling.json')
    rt={s:read(out/f's{s}_complete.json') for s in [2,3]};retrieval_seconds=sum(v['seconds'] for v in rt.values());throughput=len(data)/retrieval_seconds;hours=1732544/throughput/3600
    ft=read(out/'features_walltime.json');serial_retrieval_seconds=retrieval_seconds;measured_feature_seconds=ft['seconds'];parallel=None;parallel_features=None
    if (V2/'benchmark_parallel/benchmark.json').exists():
        parallel=read(V2/'benchmark_parallel/benchmark.json');retrieval_seconds=parallel['seconds'];throughput=len(data)/retrieval_seconds;hours=1732544/throughput/3600
