    endtoend_hours=(retrieval_seconds+measured_feature_seconds)*1732544/len(data)/3600
    featpeaks=[read(p)['memory']['peak_rss_bytes'] for p in out.glob('s*_features_complete_*.json')];peak=max(sum(featpeaks),selection['memory']['peak_rss_bytes'],max(v['memory']['peak_rss_bytes'] for v in rt.values()))
    if parallel:peak=max(peak,parallel['peak_ram_bound'])
    if parallel_features:peak=max(peak,parallel_features['peak_ram_bound'])
    disk=sum(p.stat().st_size for p in V2.rglob('*') if p.is_file());v1=read(V1/'run_6000/final_results.json')['models']['boosted'];v1c=read(V1/'run_6000/candidate_report_final.json')['validation']['100']
    oldpilot=read(V2/'v1_paired_fit500.json');newpilot=read(V2/'pilot_old_500_frozen/assessment.json');freshpilot=read(V2/'pilot_new_500_frozen/assessment.json')
    # Operational gates, not organizer rules. Include feature-generation cost to avoid a misleading speed claim.
