    focus += [r for r in errors if r['kind']=='false_negative' and 'classifier_miss' in r['categories'] and 'missing_address' in r['categories']][:3]
    for e in focus:
        q=byid[e['s1']];c=e['candidate'];examples.append([e['kind'],e['s1'],e['target'],q['business_name'],c['business_name'],q['business_address'],c['business_address'] or '<missing>',','.join(e['categories'])])
    compare=[]
